def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'D' if history[0][1] == 'D' else 'C'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]
    my_def = my.count('D')
    opp_def = opp.count('D')
    opp_coop_rate = (n - opp_def) / n

    if n >= 97:
        return 'D'

    if opp_def > n * 0.6:
        return 'D'

    if opp_def == 0 and n >= 15:
        if rng.random() < 0.2:
            return 'D'
        return 'C'

    if opp_coop_rate > 0.9 and n >= 20:
        if rng.random() < 0.12:
            return 'D'
        return 'C'

    last_my, last_opp = history[-1]

    if last_opp == 'D':
        if n >= 2 and history[-2][1] == 'D':
            recent_my_def = sum(1 for a in my[-4:] if a == 'D')
            if recent_my_def >= 3:
                return 'C'
            return 'D'
        if last_my == 'D':
            return 'C'
        else:
            if rng.random() < 0.15:
                return 'C'
            return 'D'
    else:
        if last_my == 'D':
            return 'C'
        if n < 90 and rng.random() < 0.05:
            return 'D'
        return 'C'
